protected static str getCacheId(ClassName _providerClassName)
{
    return _providerClassName + strLwr(curExt());
}

/// <summary>
/// The version number that the provider returns to the TFMVersionProvider (used by the TFMDocApplicationConfiguration)
/// </summary>
/// <returns></returns>
abstract public str version()
{
}

/// <summary>
/// Return provider objects.
/// </summary>
/// <param name = "_includeNonSingletons">If True, it will return providers that is not an singleton. Therefore it will contstruct a provider in that case.</param>
/// <returns></returns>
public static Set getProviders(boolean _includeNonSingletons = false)
{
    ListEnumerator  providerClasses = new SysDictClass(classNum(TFMProvider)).extendedBy(true).getEnumerator();
    TFMProvider     provider;
    SysDictClass    sdc;
    Set             providers = new Set(Types::Class);
    while (providerClasses.moveNext())
    {
        sdc = new SysDictClass(providerClasses.current());
        if (sdc.hasStaticMethod(staticMethodStr(TFMPagesProvider,instance)))
        {
            provider = sdc.callStatic(staticMethodStr(TFMPagesProvider,instance));
            if (provider)
            {
                providers.add(provider);
            }
        } 
        else if(_includeNonSingletons && !sdc.isAbstract())
        {
            providers.add(sdc.makeObject());
        }
    }
    return providers;
}

public static void invalidateProviders()
{
    ListEnumerator  providerClasses = new SysDictClass(classNum(TFMProvider)).extendedBy(true).getEnumerator();
    TFMProvider     provider;
    SysDictClass    sdc;
    SetEnumerator   providers = TFMProvider::getProviders().getEnumerator();
    while (providers.moveNext())
    {
        provider = providers.current();
        provider.invalidateProvider(false);
    }
}
